// TestTextChrome compares text layout with Chromium (testdata/text,
// regenerated by `make crosscheck` with scripts/textcheck.cjs, which loads
// the bundled fonts through @font-face). Compared exactly, in 1/64 px:
// the border box of every element and anonymous text box, and for every
// line its text, left edge, top, width and height. Lines that end in an
// ellipsis are compared by count only (Chromium reports the untruncated
// characters). knownTextDiffs lists accepted mismatches.

var knownTextDiffs = map[string]knownText{
	// Flex shrinking of items with fractional (text) widths: our exact
	// distribution and Chromium's float steps round 1/64 px apart.
	"nested": {"D14 sub-pixel rounding of flex shrink", 1},

	// Seeded random documents (text_random_test.go).
	"random_0001": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0004": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0007": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0014": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0023": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0039": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0045": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0048": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0057": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0069": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0072": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0073": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0089": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0097": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0104": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0168": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0175": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0192": {"D23 kerning across a soft line break", 32},
	"random_0193": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0198": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0202": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0214": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0217": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0223": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0238": {"D23 kerning across a soft line break", 32},
	"random_0244": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0252": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0254": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0255": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0274": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0275": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0282": {"D14 sub-pixel rounding of flex sizes", 2},
	"random_0292": {"D14 sub-pixel rounding of flex sizes", 2},
}

type knownText struct {
	why string
	tol geom.Unit // allowed difference per coordinate, in 1/64 px
}

func near(a, b, tol geom.Unit) bool { return a-b <= tol && b-a <= tol }

type chromeText struct {
	Boxes [][4]float64
	Lines [][][]any
}

func toUnit(f float64) geom.Unit { return geom.Unit(math.Round(f * 64)) }

func readChromeText(t *testing.T, file string) map[string]chromeText {
	b, err := os.ReadFile(filepath.Join("..", "..", "testdata", "text", file))
	if err != nil {
		t.Fatalf("%v; run `make crosscheck`", err)
	}
	var chrome map[string]chromeText
	if err := json.Unmarshal(b, &chrome); err != nil {
		t.Fatal(err)
	}
	return chrome
}

func TestEmitText(t *testing.T) {
	if *emitText == "" {
		t.Skip("no -emit-text")
	}
	if err := writeRandomText(*emitText); err != nil {
		t.Fatal(err)
	}
}

// TestTextChromeRandom compares the seeded random documents.
func TestTextChromeRandom(t *testing.T) {
	chrome := readChromeText(t, "random.json")
	nb, nl := 0, 0
	for i := 0; i < randomTextCount; i++ {
		name, src := randomTextDoc(i)
		t.Run(name, func(t *testing.T) {
			b, l := compareText(t, name, []byte(src), chrome)
			nb, nl = nb+b, nl+l
		})
	}
	t.Logf("compared %d boxes and %d lines", nb, nl)
}

func TestTextChrome(t *testing.T) {
	chrome := readChromeText(t, "chrome.json")
	docs, _ := filepath.Glob(filepath.Join("..", "..", "testdata", "text", "docs", "*.html"))
	if len(docs) < 10 {
		t.Fatalf("only %d text documents", len(docs))
	}
	nBoxes, nLines := 0, 0
	for _, path := range docs {
		name := strings.TrimSuffix(filepath.Base(path), ".html")
		t.Run(name, func(t *testing.T) {
			src, _ := os.ReadFile(path)
			b, l := compareText(t, name, src, chrome)
			nBoxes, nLines = nBoxes+b, nLines+l
		})
	}
	t.Logf("compared %d boxes and %d lines", nBoxes, nLines)
}

// compareText checks one document against Chromium's data and returns the
// number of boxes and lines compared.
func compareText(t *testing.T, name string, src []byte, chrome map[string]chromeText) (nBoxes, nLines int) {
	want, ok := chrome[name]
	if !ok {
		t.Fatalf("no Chromium data; run `make crosscheck`")
	}
	known, isKnown := knownTextDiffs[name]
	errs, nBoxes, nLines, warns := diffText(src, want, known.tol)
	if len(warns) > 0 {
		t.Errorf("warnings: %q", warns)
	}
	if isKnown {
		t.Logf("tolerance %v (%s)", known.tol, known.why)
		// Self-check: a listed case must still need its tolerance.
		if exact, _, _, _ := diffText(src, want, 0); len(errs) == 0 && len(exact) == 0 {
			t.Errorf("now matches Chromium exactly; remove it from knownTextDiffs")
		}
	}
	if len(errs) > 0 {
		t.Errorf("%d differences:\n%s", len(errs), strings.Join(errs, "\n"))
	}
	return
}

// diffText lays out src and lists its differences from Chromium's data,
// allowing tol (1/64 px) per coordinate.
func diffText(src []byte, want chromeText, tol geom.Unit) (errs []string, nBoxes, nLines int, warns []string) {
	m := sizeRE.FindSubmatch(src)
	var w, h int
	fmt.Sscan(string(m[1]), &w)
	fmt.Sscan(string(m[2]), &h)
	d := Build(string(src), "")
	d.Layout(w, h)
	var boxes []*Box
	var all func(b *Box)
	all = func(b *Box) {
		boxes = append(boxes, b)
		for _, k := range b.Kids {
			all(k)
		}
	}
	all(d.Root)
	if len(boxes) != len(want.Boxes) {
		return []string{fmt.Sprintf("%d boxes, Chromium has %d", len(boxes), len(want.Boxes))}, 0, 0, d.Warnings
	}
	nearR := func(a, b [4]geom.Unit) bool {
		return near(a[0], b[0], tol) && near(a[1], b[1], tol) && near(a[2], b[2], tol) && near(a[3], b[3], tol)
	}
	ti := 0
	for i, bx := range boxes {
		wb := want.Boxes[i]
		got := [4]geom.Unit{bx.Abs.X, bx.Abs.Y, bx.Abs.W, bx.Abs.H}
		exp := [4]geom.Unit{toUnit(wb[0]), toUnit(wb[1]), toUnit(wb[2]), toUnit(wb[3])}
		nBoxes++
		if !nearR(got, exp) {
			errs = append(errs, fmt.Sprintf("box %d (%s): got %v want %v", i, label(bx), fmtR(got), fmtR(exp)))
		}
		if bx.Text == nil {
			continue
		}
		wl := want.Lines[ti]
		ti++
		tx := bx.Text
		blk := tx.Layout(bx.Abs.W)
		if len(blk.Lines) != len(wl) {
			errs = append(errs, fmt.Sprintf("box %d %q: %d lines, Chromium %d", i, tx.String(), len(blk.Lines), len(wl)))
			continue
		}
		for k, ln := range blk.Lines {
			nLines++
			if ln.Ellipsis {
				continue // Chromium reports the untruncated characters
			}
			str := tx.Runes(ln.Start, ln.End)
			if tx.Params().WhiteSpace != style.WhiteSpacePre {
				str = strings.TrimRight(str, " ")
			}
			g := [4]geom.Unit{bx.Abs.X + ln.X, bx.Abs.Y + ln.Baseline - tx.Ascent(), tx.InkWidth(&ln), tx.Ascent() + tx.Descent()}
			c := wl[k]
			e := [4]geom.Unit{toUnit(c[1].(float64)), toUnit(c[2].(float64)), toUnit(c[3].(float64)), toUnit(c[4].(float64))}
			if str != c[0] || !nearR(g, e) {
				errs = append(errs, fmt.Sprintf("box %d line %d:\n   got  %q %s\n   want %q %s", i, k, str, fmtR(g), c[0], fmtR(e)))
			}
		}
	}
	return errs, nBoxes, nLines, d.Warnings
}

func label(b *Box) string {
	if b.El != nil {
		return b.El.Tag()
	}
	s := b.Text.String()
	if len(s) > 20 {
		s = s[:20] + "…"
	}
	return fmt.Sprintf("text %q", s)
}

func fmtR(r [4]geom.Unit) string {
	return fmt.Sprintf("[%v %v %v %v]", r[0], r[1], r[2], r[3])
}
